
INSERT INTO public.reviews (name, email, rating, feedback, sentiment, approved, created_at) VALUES
-- Batch 1: Positive reviews (1-50)
('Maria Santos', 'maria.s@email.com', 5, 'Absolutely love Pizza Volante! The pepperoni pizza is hands down the best in town. Crispy crust, generous toppings, and the cheese pull is insane. Will definitely be back!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('John Rivera', 'john.r@email.com', 5, 'Amazing fried chicken! So crispy on the outside and juicy inside. The gravy was perfect too.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Angela Cruz', 'angela.c@email.com', 5, 'Best pasta carbonara I''ve ever had! Creamy, rich, and perfectly seasoned. The staff was super friendly too.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Miguel Torres', 'miguel.t@email.com', 4, 'Great pizza and the ambiance is really cozy. Perfect for date nights. The Hawaiian pizza was delicious.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Sofia Garcia', 'sofia.g@email.com', 5, 'We ordered the family meal deal and it was incredible value! Two large pizzas, pasta, and drinks for a great price. Everything was fresh and hot.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Carlos Reyes', 'carlos.r@email.com', 4, 'The meat lovers pizza never disappoints. Came in 20 minutes too. Fast delivery!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Isabella Mendoza', 'isabella.m@email.com', 5, 'Celebrated my birthday here and the staff went above and beyond! They even brought out a surprise dessert. The food was exceptional.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('David Kim', 'david.k@email.com', 4, 'Really good margherita pizza. Simple but so flavorful. The basil was fresh and the sauce was spot on.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Patricia Lim', 'patricia.l@email.com', 5, 'The iced tea here is so refreshing! And the garlic bread is to die for. Always a great experience dining at Pizza Volante.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Roberto Aquino', 'roberto.a@email.com', 5, 'Five stars! The supreme pizza is loaded with toppings. You can taste the quality ingredients. This is our family''s go-to pizza place.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Emily Chen', 'emily.c@email.com', 4, 'Tried the new BBQ chicken pizza and it was really good. The sauce had a nice smoky flavor.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Marco Villanueva', 'marco.v@email.com', 5, 'The pasta aglio olio here is simple perfection. Perfectly al dente with just the right amount of garlic and chili flakes.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Anna Dela Cruz', 'anna.dc@email.com', 5, 'Love the cozy ambiance and the warm lighting. Makes every meal feel special. The four cheese pizza is heavenly!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('James Tan', 'james.t@email.com', 4, 'Solid fried chicken meal. Generous portion, crispy coating, and the rice was fluffy. Good value for money.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Rachel Gomez', 'rachel.g@email.com', 5, 'We always order from Pizza Volante for office parties. Never had a single complaint from anyone. The pizza is consistently great!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Luis Fernandez', 'luis.f@email.com', 4, 'The service was quick and the staff remembered my usual order. That''s the kind of personal touch I appreciate.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Diana Ramos', 'diana.r@email.com', 5, 'Brought my kids here and they absolutely loved it! The kiddie meals are well portioned and the staff was so patient with them.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Kevin Santos', 'kevin.s@email.com', 5, 'Their thin crust pizza is the best! Light, crispy, and you can actually taste the toppings. Not drowning in dough like other places.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Christine Bautista', 'christine.b@email.com', 4, 'Nice place for a quick lunch. The combo meal is a great deal - pizza slice, drink, and a side for a reasonable price.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Andrew Lopez', 'andrew.l@email.com', 5, 'The calzone is underrated here! Stuffed with so much filling and the crust is golden brown. Highly recommend trying it.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Grace Navarro', 'grace.n@email.com', 5, 'First time here and I''m already a fan. The cheese pizza was so simple yet so satisfying. The dough has a slight chewiness that''s perfect.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Benjamin Ocampo', 'benjamin.o@email.com', 4, 'The fried chicken wings are addictive! Perfectly seasoned and the dipping sauce is amazing. Great beer pairing too.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Samantha Reyes', 'samantha.r@email.com', 5, 'Everything about this place screams quality. From the fresh ingredients to the friendly staff. Pizza Volante is a gem!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Patrick Castillo', 'patrick.c@email.com', 4, 'Ordered delivery and the pizza arrived hot and fresh. Packaging was neat and nothing was soggy. Impressed!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Nicole Flores', 'nicole.f@email.com', 5, 'The mushroom truffle pizza is an absolute must-try! Rich and earthy flavors. Worth every peso.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Ryan Dizon', 'ryan.d@email.com', 4, 'Great spot for watching sports with friends. TVs are placed well, the beer is cold, and the pizza keeps coming. What more could you want?', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Katherine Soriano', 'katherine.s@email.com', 5, 'I''m gluten sensitive and they have great options for me! The gluten-free crust is actually tasty, not cardboard-like.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Mark Evangelista', 'mark.e@email.com', 5, 'Outstanding customer service! They fixed my order immediately when I mentioned a missing item. No questions asked.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Camille Padilla', 'camille.p@email.com', 4, 'The lasagna is rich and cheesy. Definitely comfort food at its finest. Will order again!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Joseph Manalo', 'joseph.m@email.com', 5, 'Pizza Volante has the best dough in the city. You can tell they let it rise properly. The texture is just right.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Trisha Gutierrez', 'trisha.g@email.com', 4, 'Really enjoyed the salad bar! Fresh greens and the vinaigrette was delicious. Nice healthy option alongside the pizza.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Vincent Cruz', 'vincent.c@email.com', 5, 'Took my girlfriend here for our anniversary and it was perfect. Romantic setting, excellent food, and attentive staff.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Bianca Salazar', 'bianca.s@email.com', 4, 'The mango shake is so thick and creamy! And the pepperoni pizza was loaded. Definitely coming back.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Daniel Aguilar', 'daniel.a@email.com', 5, 'Best pizza delivery experience! Arrived in 25 minutes, still piping hot. The driver was courteous too.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Michelle Chua', 'michelle.c@email.com', 5, 'We''ve been loyal customers for 3 years and the quality has never dropped. Consistency is key and Pizza Volante nails it.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Jason Bernal', 'jason.b@email.com', 4, 'The spicy Italian sausage pizza packs a punch! Love the heat. Great with a cold lemonade.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Veronica Del Rosario', 'veronica.dr@email.com', 5, 'Clean restaurant, well-maintained restrooms, and the food is always fresh. This is how you run a pizza place!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Alex Morales', 'alex.m@email.com', 4, 'Their garlic parmesan wings are incredible. Perfectly crispy and the garlic flavor is spot on without being overpowering.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Hannah Javier', 'hannah.j@email.com', 5, 'I ordered the family feast for a get together and everyone was raving about the food. The variety is impressive!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Gabriel Santiago', 'gabriel.s@email.com', 4, 'Quick service even during lunch rush. Got my order in 15 minutes. The staff handles the crowd well.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Leah Pascual', 'leah.p@email.com', 5, 'The tiramisu here is the real deal! Perfectly balanced coffee and mascarpone flavors. Amazing dessert to end a great meal.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Aaron Velasco', 'aaron.v@email.com', 4, 'Good music playlist in the restaurant. Creates a nice vibe while eating. Food is great too!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Jasmine Reyes', 'jasmine.r@email.com', 5, 'The extra cheese pizza with stuffed crust is pure indulgence. So cheesy and satisfying. My cheat day go-to!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Nathan Gonzales', 'nathan.g@email.com', 5, 'Friendly staff that makes you feel welcome. The manager even came by our table to check on us. Great hospitality!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Angelica Dela Pena', 'angelica.dp@email.com', 4, 'Love that they use fresh mozzarella! You can really taste the difference. The caprese pizza is wonderful.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Timothy Hernandez', 'timothy.h@email.com', 5, 'Pizza Volante never lets me down. Consistent quality every single time. The pepperoni and mushroom combo is my favorite.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Monica Fuentes', 'monica.f@email.com', 4, 'The new chicken alfredo pasta is really creamy and delicious. Not too heavy, perfectly portioned.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Christopher Roque', 'christopher.r@email.com', 5, 'Brought my visiting relatives here and they were so impressed! They said it rivals pizza places in Manila.', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Amanda Torres', 'amanda.t@email.com', 5, 'The breakfast pizza is a genius creation! Eggs, bacon, and cheese on a perfect crust. Saturday morning favorite!', 'positive', true, now() - interval '1 day' * floor(random() * 30)),
('Eduardo Luna', 'eduardo.l@email.com', 4, 'Solid pizza place. Fair prices, good taste, nice people. What else do you need?', 'positive', true, now() - interval '1 day' * floor(random() * 30)),

-- Batch 1: Neutral reviews (51-70)
('Laura Villareal', 'laura.v@email.com', 3, 'The pizza was okay. Nothing special but nothing bad either. Average pizza place experience.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Richard Santos', 'richard.s@email.com', 3, 'Decent food but the place was a bit noisy. The pizza was standard. Might try a different item next time.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Jennifer Cruz', 'jennifer.c@email.com', 3, 'Food arrived on time. Pizza was warm. Tasted like regular pizza. Nothing extraordinary.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Steven Ramirez', 'steven.r@email.com', 3, 'It''s an alright pizza joint. The crust could use more flavor but the toppings were fine.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Teresa Bautista', 'teresa.b@email.com', 3, 'Went here because it was near. Pizza was decent. Wouldn''t go out of my way but if I''m in the area, sure.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Francis Lim', 'francis.l@email.com', 3, 'Ordered the fried chicken and rice meal. It was filling but nothing memorable. Standard fast food quality.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Melissa Tan', 'melissa.t@email.com', 3, 'The pasta was okay. Sauce was a bit bland but the portion was generous. Average dining experience.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Ronald Garcia', 'ronald.g@email.com', 3, 'Price is fair for what you get. Not the best pizza I''ve had but definitely not the worst. It''s fine.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Carmela Reyes', 'carmela.r@email.com', 3, 'The ambiance is nice but the food didn''t really stand out to me. It was just regular pizza.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Bryan Navarro', 'bryan.n@email.com', 3, 'Had the combo meal. Pizza was lukewarm when it arrived but tasted decent enough. Service was normal.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Sandra Ocampo', 'sandra.o@email.com', 3, 'Nothing to complain about but nothing to rave about either. Just a regular pizza dinner.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Tony Castillo', 'tony.c@email.com', 3, 'The restaurant is clean and the staff is polite. Food is average. Not bad, not great.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Donna Flores', 'donna.f@email.com', 3, 'Tried the carbonara pasta. It was okay, a bit too creamy for my taste. The garlic bread was better though.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Philip Dizon', 'philip.d@email.com', 3, 'Standard pizza delivery. Came in a reasonable time. Pizza was as expected. Nothing special.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Lorna Soriano', 'lorna.s@email.com', 3, 'We ate here because it was the closest option. Food was fine. Kids didn''t complain so that''s a plus I guess.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Dennis Evangelista', 'dennis.e@email.com', 3, 'The pizza crust was a bit too thick for my liking but the toppings were decent. An okay meal overall.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Victoria Padilla', 'victoria.p@email.com', 3, 'Ordered takeout. Everything was packed properly. Taste was standard. Not much to say honestly.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Raymond Manalo', 'raymond.m@email.com', 3, 'It''s a typical pizza restaurant. Clean, decent food, reasonable prices. Does the job.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('Carla Gutierrez', 'carla.g@email.com', 3, 'The drink selection is limited. Pizza was average. Could use more sauce. Otherwise an okay visit.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),
('George Salazar', 'george.s@email.com', 3, 'Waited about 30 minutes for our food which is normal. Pizza was decent. Nothing I''d write home about.', 'neutral', true, now() - interval '1 day' * floor(random() * 30)),

-- Batch 1: Negative reviews (71-100)
('Mario Del Valle', 'mario.dv@email.com', 1, 'Terrible experience. Pizza arrived cold and soggy. The delivery took over an hour. Never ordering again.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Linda Ramos', 'linda.r@email.com', 2, 'The fried chicken was dry and overcooked. The coating was bland and tasteless. Very disappointing.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Ferdinand Torres', 'ferdinand.t@email.com', 1, 'Found a hair in my pasta. Absolutely disgusting. Lost my appetite completely. Will never come back.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Rosemary Cruz', 'rosemary.c@email.com', 2, 'Way too expensive for the quality. The pizza was mediocre at best. There are better options for less money.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Albert Mendoza', 'albert.m@email.com', 1, 'The staff was rude and inattentive. Had to call them multiple times just to get water. Food took 45 minutes.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Gloria Aquino', 'gloria.a@email.com', 2, 'Pizza was undercooked. The center was still doughy. Had to send it back. Second attempt was barely better.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Henry Fernandez', 'henry.f@email.com', 1, 'Got food poisoning after eating here. Stomach cramps all night. This is unacceptable. Will report to health department.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Rosa Bernal', 'rosa.b@email.com', 2, 'The pasta was overcooked and mushy. The sauce tasted like it came from a can. Not worth the price.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Oscar Javier', 'oscar.j@email.com', 1, 'Worst pizza I''ve ever had. Barely any cheese, stale crust, and the toppings were sparse. Complete waste of money.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Cynthia Santiago', 'cynthia.s@email.com', 2, 'The restaurant was filthy. Tables were sticky and the floor was dirty. Lost my appetite before the food even arrived.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Armando Pascual', 'armando.p@email.com', 1, 'They got my order wrong twice. The manager didn''t even apologize. Terrible customer service all around.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Elvira Velasco', 'elvira.v@email.com', 2, 'The drinks were warm and flat. Pizza was greasy and heavy. Left feeling sick. Not coming back.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Ricardo Gonzales', 'ricardo.g@email.com', 1, 'Waited an hour for delivery and when it arrived, the order was incomplete. Missing the pasta and drinks. Frustrating!', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Felicia Dela Pena', 'felicia.dp@email.com', 2, 'The fried chicken was so oily. Like, swimming in oil. And it was cold in the middle. Gross.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Arturo Hernandez', 'arturo.h@email.com', 1, 'Overpriced garbage. Small portions, bad taste, slow service. How is this place still open?', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Norma Fuentes', 'norma.f@email.com', 2, 'The salad was wilted and the dressing tasted off. The pizza was okay but nothing impressive. Won''t return.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Raul Roque', 'raul.r@email.com', 1, 'Music was way too loud. Couldn''t have a conversation. Food was cold when it arrived. Terrible experience overall.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Esperanza Luna', 'esperanza.l@email.com', 2, 'Parking is a nightmare and the waiting area is too small. When we finally got seated, the pizza was below average.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Alejandro Villareal', 'alejandro.v@email.com', 2, 'The cheese on the pizza was rubbery and tasteless. Felt like plastic. Very unimpressive for the price.', 'negative', true, now() - interval '1 day' * floor(random() * 30)),
('Beatriz Ramirez', 'beatriz.r@email.com', 1, 'Asked for no onions and got extra onions instead. When I complained, the staff just shrugged. Ridiculous.', 'negative', true, now() - interval '1 day' * floor(random() * 30));
